public RefreshFrequency xds()
{
    METInventDimByLocationPolicyTmp      metInventDimByLocationPolicyTmp;
    METUserSecurityGroupList             metUserSecurityGroupList, blankGroupList;
    METUserSecurityWarehouseList         metUserSecurityWarehouseList, blankWarehouseList;
    InventLocation                       inventLocation;
    InventDim                            inventDim;

    Unchecked(Uncheck::XDS)
    {
        while select crosscompany InventDimId, DataAreaId from inventDim
                group by InventDim.InventDimId, InventDim.DataAreaId
                where inventDim.InventSiteId != ''
            join inventLocation
                where inventLocation.InventSiteId  == inventDim.InventSiteId
                    && inventLocation.DataAreaId    == inventDim.DataAreaId
            join metUserSecurityWarehouseList
                where metUserSecurityWarehouseList.InventLocationId == inventLocation.InventLocationId
                    && metUserSecurityWarehouseList.Company          == inventLocation.DataAreaId
            join metUserSecurityGroupList
                where metUserSecurityGroupList.UserSecurityGroupId == metUserSecurityWarehouseList.UserSecurityGroupId
                    && metUserSecurityGroupList.UserId              == curUserId()
        {
            metInventDimByLocationPolicyTmp.InventDimId = inventDim.InventDimId;
            metInventDimByLocationPolicyTmp.Company     = inventDim.DataAreaId;
            metInventDimByLocationPolicyTmp.insert();

        }

        while select Company from metInventDimByLocationPolicyTmp
            group by metInventDimByLocationPolicyTmp.Company
        {
            metInventDimByLocationPolicyTmp.InventDimId = METconstants::AllowBlank;
            metInventDimByLocationPolicyTmp.Company     = metInventDimByLocationPolicyTmp.Company;
            metInventDimByLocationPolicyTmp.insert();
        }

        return RefreshFrequency::PerSession;
    }
}
